import { cookies, headers } from 'next/headers'

function parsePreferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) return 'unknown'
  return acceptLanguage.split(',')[0]?.split(';')[0]?.trim() || 'unknown'
}

export default async function ThemePreference() {
  const cookieStore = await cookies()
  const headerStore = await headers()

  const theme = cookieStore.get('theme')?.value || 'light'
  const language = parsePreferredLanguage(headerStore.get('accept-language'))

  return (
    <section>
      <p>
        Current theme: <strong>{theme}</strong>
      </p>
      <p>
        Preferred language: <strong>{language}</strong>
      </p>
    </section>
  )
}

